#!/usr/bin/env python3
"""Generate and validate the ray-visible palette table from original texture source colours."""

from __future__ import annotations

import hashlib
import json
from pathlib import Path
import sys

ROOT = Path(__file__).resolve().parents[1] / "games/ai_village/mods/ai_bridge"
SOURCE = ROOT / "textures/palette.json"
OUTPUT = ROOT / "palette_generated.lua"


def generated() -> str:
    raw = SOURCE.read_bytes()
    colours = json.loads(raw)
    digest = hashlib.sha256(raw).hexdigest()
    lines = [
        "-- Generated by ../../../../tools/generate_palette.py; do not edit.",
        f'local source_sha256 = "{digest}"',
        "local colours = {",
    ]
    for name, rgb in sorted(colours.items()):
        if len(rgb) != 3 or any(not isinstance(value, int) or value < 0 or value > 255 for value in rgb):
            raise ValueError(f"{name}: expected three 0..255 average texture channels")
        lines.append(f'  ["{name}"] = {{{rgb[0]}, {rgb[1]}, {rgb[2]}}},')
    lines += ["}", "return { source_sha256 = source_sha256, colours = colours }", ""]
    return "\n".join(lines)


def main() -> int:
    expected = generated()
    if len(sys.argv) == 2 and sys.argv[1] == "--check":
        if not OUTPUT.exists() or OUTPUT.read_text() != expected:
            print("palette_generated.lua is stale; run tools/generate_palette.py", file=sys.stderr)
            return 1
        return 0
    OUTPUT.write_text(expected)
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
